@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:Product,
                        schema1:Thing,
                        prov:Entity ;
                    schema1:additionalProperty [ a schema1:PropertyValue ;
                            schema1:name "collimation technique" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/collimation> ;
                            schema1:value "none" ],
                        [ a schema1:PropertyValue ;
                            schema1:name "harmonic_rejection" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/harmonicrejection> ;
                            schema1:value "Rh-coated mirror, detuned" ],
                        [ a schema1:PropertyValue ;
                            schema1:name "focusing" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/focusing> ;
                            schema1:value "???" ] ;
                    schema1:additionalType <https://w3id.org/cdif/xas/beamline>,
                        <https://www.wikidata.org/entity/Q3099911> ;
                    schema1:identifier "should have a registry with URIs" ;
                    schema1:name "13-BM-D" ] ;
            sh:resultMessage "An instrument should have a category classification from a controlled vocabulary (schema:category)." ;
            sh:resultPath schema1:category ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape _:na34ecb33841942beb5553ad3fdbee351b415 ],
        [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:Product,
                        schema1:Thing,
                        prov:Entity ;
                    schema1:additionalProperty [ a schema1:PropertyValue ;
                            schema1:name "monitor preset" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/monitorpreset> ;
                            schema1:value "N.A." ],
                        [ a schema1:PropertyValue ;
                            schema1:alternateName "transmitted flux measurement method" ;
                            schema1:name "detector mode it" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/detectorit> ;
                            schema1:value "10cm  N2" ],
                        [ a schema1:PropertyValue ;
                            schema1:alternateName "incident flux measurement method" ;
                            schema1:name "detector mode i0" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/detectori0> ;
                            schema1:value "10cm  N2" ],
                        [ a schema1:PropertyValue ;
                            schema1:name "monitor mode" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/monitormode> ;
                            schema1:value "monitor" ] ;
                    schema1:additionalType <https://w3id.org/cdif/xas/xraymonitor>,
                        <https://www.wikidata.org/entity/Q3099911> ;
                    schema1:name "x-ray intensity monitor" ] ;
            sh:resultMessage "An instrument should have a category classification from a controlled vocabulary (schema:category)." ;
            sh:resultPath schema1:category ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape _:na34ecb33841942beb5553ad3fdbee351b415 ],
        [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:Product,
                        schema1:Thing,
                        prov:Entity ;
                    schema1:additionalProperty [ a schema1:PropertyValue ;
                            schema1:name "crystal type" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/monochromatortype> ;
                            schema1:value "missing" ],
                        [ a schema1:PropertyValue ;
                            schema1:name "d-spacing" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/dspacing> ;
                            schema1:unitText "Angstrom" ;
                            schema1:value "3.13550" ],
                        [ a schema1:PropertyValue ;
                            schema1:name "reflection plane (hkl)" ;
                            schema1:propertyID <https://w3id.org/cdif/xas/reflectionplane> ;
